const retrievedItems = $input.all();

const query =
  $('Test Question').first().json.query;

if (retrievedItems.length === 0) {
  throw new Error(
    'No SEC filing passages were retrieved.'
  );
}

const passages = [];
const sources = [];

for (
  let index = 0;
  index < retrievedItems.length;
  index++
) {
  const result =
    retrievedItems[index].json;

  const document =
    result.document || {};

  const metadata =
    document.metadata || {};

  const pageContent =
    String(
      document.pageContent || ''
    ).trim();

  const score =
    result.score ?? null;

  passages.push(
    [
      `SOURCE ${index + 1}`,
      `Ticker: ${metadata.ticker || 'Unknown'}`,
      `Company: ${metadata.company_name || 'Unknown'}`,
      `Form type: ${metadata.form_type || 'Unknown'}`,
      `Filing date: ${metadata.filing_date || 'Unknown'}`,
      `Accession number: ${metadata.accession_number || 'Unknown'}`,
      `Relevance score: ${score ?? 'Not available'}`,
      `Source URL: ${metadata.source_url || 'Not available'}`,
      '',
      'PASSAGE:',
      pageContent
    ].join('\n')
  );

  sources.push({
    source_number: index + 1,
    ticker:
      metadata.ticker || null,

    company_name:
      metadata.company_name || null,

    form_type:
      metadata.form_type || null,

    filing_date:
      metadata.filing_date || null,

    accession_number:
      metadata.accession_number || null,

    source_url:
      metadata.source_url || null,

    score:
      score
  });
}

return [
  {
    json: {
      query,
      retrieved_count:
        retrievedItems.length,

      context:
        passages.join(
          '\n\n--------------------\n\n'
        ),

      sources
    }
  }
];
